]

def test_param(offset_br, divisor_br, offset_bc, divisor_bc):
    output = [[7]*4 for _ in range(4)]
    for br, bc in block_pos:
        r = int((br + offset_br) / divisor_br * 4)
        c = int((bc + offset_bc) / divisor_bc * 4)
        if r < 4 and c < 4:
            output[r][c] = 0
    return output

